Result<Unit,Text> exercise() {
    Text widthArg = Args.get(0)?;
    Text chunksArg = Args.get(1)?;
    Text roundsArg = Args.get(2)?;
    Text reuseArg = Args.get(3)?;
    int width = widthArg.parseInt()?;
    int chunks = chunksArg.parseInt()?;
    int rounds = roundsArg.parseInt()?;
    int reuse = reuseArg.parseInt()?;
    Text token = new Text("");
    int index = 0;
    while (index < width) { token.append("é\0😀"); index = index + 1; }
    Text retained = new Text("");
    long total = 0L;
    int round = 0;
    while (round < rounds) {
        if (reuse == 0) {
            Text value = new Text("");
            index = 0;
            while (index < chunks) { value.appendText(token); index = index + 1; }
            total = total + (long)value.byteLength() + (long)value.byteAt(round % value.byteLength());
        } else {
            retained.clear();
            index = 0;
            while (index < chunks) { retained.appendText(token); index = index + 1; }
            total = total + (long)retained.byteLength() + (long)retained.byteAt(round % retained.byteLength());
        }
        round = round + 1;
    }
    println(total);
    return new Result<Unit,Text>.Ok(());
}
void main() {
    match (exercise()) {
        Ok(unit) { println("DONE"); }
        Err(error) { Console.print("ERROR: "); Console.printText(error); println(""); }
    }
}

